 "content": "def transform(grid):
    # Fill the interiors of outlined rectangular objects with the mapped fill color.
    from collections import deque
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    bg=g[0][0]
    # Find same-color components by 4-connectivity; outlines are connected rings.
    seen=set()
    for r in range(h):
      for c in range(w):
        col=g[r][c]
        if col==bg or (r,c) in seen: continue
        q=[(r,c)]; seen.add((r,c)); cells=[]
        for y,x in q:
          cells.append((y,x))
          for yy,xx in ((y+1,x),(y-1,x),(y,x+1),(y,x-1)):
            if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and g[yy][xx]==col:
              seen.add((yy,xx)); q.append((yy,xx))
        minr=min(y for y,x in cells); maxr=max(y for y,x in cells)
        minc=min(x for y,x in cells); maxc=max(x for y,x in cells)
        # Fill all background cells strictly within rectangular bounds.
        fill={1:7,3:2,5:7,9:7,6:7}.get(col,7)
        for y in range(minr+1,maxr):
          for x in range(minc+1,maxc):
            if g[y][x]==bg: g[y][x]=fill
    return g
